<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$mes=$_GET['mes']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$mes))$mes=date('Y-m');$ini=$mes.'-01';$fin=date('Y-m-t',strtotime($ini));
function dval(PDO $p,string $sql,array $a=[]):float{$s=$p->prepare($sql);$s->execute($a);return (float)$s->fetchColumn();}
$cotNum=dval($pdo,"SELECT COUNT(*) FROM cotizaciones WHERE fecha BETWEEN ? AND ? AND estado<>'Cancelado'",[$ini,$fin]);$cotTotal=dval($pdo,"SELECT COALESCE(SUM(total),0) FROM cotizaciones WHERE fecha BETWEEN ? AND ? AND estado<>'Cancelado'",[$ini,$fin]);$cob=dval($pdo,'SELECT COALESCE(SUM(monto),0) FROM pagos WHERE fecha BETWEEN ? AND ?',[$ini,$fin]);$gas=dval($pdo,'SELECT COALESCE(SUM(monto),0) FROM gastos WHERE fecha BETWEEN ? AND ?',[$ini,$fin]);$cr=dval($pdo,'SELECT COALESCE(SUM(monto),0) FROM costos_reales WHERE fecha BETWEEN ? AND ?',[$ini,$fin]);$saldo=dval($pdo,"SELECT COALESCE(SUM(GREATEST(0,c.total-COALESCE((SELECT SUM(p.monto) FROM pagos p WHERE p.cotizacion_id=c.id),0))),0) FROM cotizaciones c WHERE c.estado<>'Cancelado'");$low=(int)$pdo->query('SELECT COUNT(*) FROM inventario WHERE activo=1 AND stock<=stock_minimo')->fetchColumn();$orders=(int)$pdo->query("SELECT COUNT(*) FROM compras WHERE estatus IN ('Solicitado','Pagado','En tránsito')")->fetchColumn();$post=(int)$pdo->query("SELECT COUNT(*) FROM postventa_recordatorios WHERE estado='Pendiente' AND fecha_recordatorio<=DATE_ADD(CURDATE(),INTERVAL 30 DAY)")->fetchColumn();
$today=$pdo->query("SELECT a.*,c.cliente,c.vehiculo,c.folio FROM agenda_trabajos a LEFT JOIN cotizaciones c ON c.id=a.cotizacion_id WHERE CURDATE() BETWEEN a.fecha_inicio AND COALESCE(a.fecha_entrega,a.fecha_inicio) ORDER BY a.hora_inicio,a.id")->fetchAll();$recent=$pdo->query("SELECT c.*,COALESCE((SELECT SUM(p.monto) FROM pagos p WHERE p.cotizacion_id=c.id),0) pagado FROM cotizaciones c ORDER BY c.id DESC LIMIT 8")->fetchAll();$alerts=$pdo->query("SELECT nombre,stock,stock_minimo,unidad FROM inventario WHERE activo=1 AND stock<=stock_minimo ORDER BY stock-stock_minimo LIMIT 8")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard · SRNU CUSTOM</title><link rel="icon" href="favicon.png"><?=srnu_ui_head()?></head><body><?php srnu_appbar('dashboard');?><main class="w"><div class="srnu-page-heading"><div><h1>Centro de control SRNU</h1><p>Ventas, operación, inventario y seguimiento en un solo lugar.</p></div><form class="toolbar"><input type="month" name="mes" value="<?=eh($mes)?>"><button class="btn">Cambiar mes</button></form></div><div class="kpi-grid"><div class="kpi"><span class="srnu-stat-accent"></span><small>Cotizado en el mes</small><strong><?=emoney($cotTotal)?></strong><span class="muted"><?=number_format($cotNum)?> cotización(es)</span></div><div class="kpi"><span class="srnu-stat-accent"></span><small>Cobrado en el mes</small><strong><?=emoney($cob)?></strong><span class="muted">Pagos registrados</span></div><div class="kpi"><span class="srnu-stat-accent"></span><small>Gastos + costos reales</small><strong><?=emoney($gas+$cr)?></strong><span class="muted">Flujo neto: <?=emoney($cob-$gas-$cr)?></span></div><div class="kpi"><span class="srnu-stat-accent"></span><small>Saldo pendiente global</small><strong><?=emoney($saldo)?></strong><span class="muted">Por cobrar</span></div></div><div class="grid-3" style="margin-top:16px"><a class="card" style="text-decoration:none;color:inherit" href="inventario.php"><h3>Inventario</h3><strong style="font-size:30px"><?=$low?></strong><p class="muted">artículos en stock mínimo o menor</p></a><a class="card" style="text-decoration:none;color:inherit" href="compras.php"><h3>Pedidos abiertos</h3><strong style="font-size:30px"><?=$orders?></strong><p class="muted">solicitados, pagados o en tránsito</p></a><a class="card" style="text-decoration:none;color:inherit" href="postventa.php"><h3>Postventa</h3><strong style="font-size:30px"><?=$post?></strong><p class="muted">recordatorios próximos 30 días</p></a></div><div class="grid-2" style="margin-top:16px"><section class="panel" style="padding:18px"><div class="section-title"><h3>Agenda de hoy</h3><a href="agenda.php">Ver agenda</a></div><?php if(!$today):?><p class="muted">No hay trabajos programados para hoy.</p><?php else:?><table><tr><th>Hora</th><th>Trabajo</th><th>Cliente</th><th>Estado</th></tr><?php foreach($today as $r):?><tr><td><?=eh(substr((string)$r['hora_inicio'],0,5))?></td><td><b><?=eh($r['titulo'])?></b><div class="muted"><?=eh($r['responsable'])?></div></td><td><?=eh($r['cliente'])?><div class="muted"><?=eh($r['vehiculo'])?></div></td><td><?=eh($r['estado'])?></td></tr><?php endforeach;?></table><?php endif;?></section><section class="panel" style="padding:18px"><div class="section-title"><h3>Alertas de inventario</h3><a href="inventario.php">Abrir</a></div><?php if(!$alerts):?><p class="muted">Inventario sin alertas de mínimos.</p><?php else:?><table><tr><th>Artículo</th><th>Stock</th><th>Mínimo</th></tr><?php foreach($alerts as $r):?><tr><td><?=eh($r['nombre'])?></td><td><span class="badge badge-red"><?=number_format((float)$r['stock'],3)?> <?=eh($r['unidad'])?></span></td><td><?=number_format((float)$r['stock_minimo'],3)?></td></tr><?php endforeach;?></table><?php endif;?></section></div><section class="panel" style="padding:18px;margin-top:16px"><div class="section-title"><h3>Cotizaciones recientes</h3><a class="btn light" href="cotizador_rapido.php">⚡ Rápida</a><a class="btn blue" href="cotizador.php">＋ Nueva</a></div><table><thead><tr><th>Folio</th><th>Cliente</th><th>Vehículo</th><th>Estado</th><th>Total</th><th>Saldo</th><th></th></tr></thead><tbody><?php foreach($recent as $r):$pg=(float)$r['pagado'];if(!$pg&&!empty($r['conservar_anticipo_recibido']))$pg=(float)$r['anticipo_recibido_monto'];?><tr><td><?=eh($r['folio'])?></td><td><?=eh($r['cliente'])?></td><td><?=eh($r['vehiculo'])?></td><td><span class="badge badge-blue"><?=eh($r['estado'])?></span></td><td><?=emoney($r['total'])?></td><td><?=emoney(max(0,(float)$r['total']-$pg))?></td><td><a href="cotizador.php?id=<?=$r['id']?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></section><section class="panel" style="padding:18px;margin-top:16px"><h3>Accesos rápidos</h3><div class="toolbar"><a class="btn blue" href="cotizador.php">Nueva cotización</a><a class="btn light" href="cotizador_rapido.php">⚡ Cotización rápida</a><a class="btn light" href="agenda.php">Agenda</a><a class="btn light" href="inventario.php">Inventario</a><a class="btn light" href="compras.php">Compras</a><a class="btn light" href="gastos.php">Gastos</a><a class="btn light" href="caja.php">Caja</a><a class="btn light" href="vehiculos.php">Expedientes</a><a class="btn light" href="postventa.php">Postventa</a><a class="btn light" href="plantillas.php">Plantillas</a><a class="btn light" href="reportes.php">Reportes</a></div></section></main></body></html>
